1	import { describe, test, expect } from 'vitest';
2	import { flattenRefinementValues } from './refinementValues';
3	
4	describe('flattenRefinementValues', () => {
5	  test('returns an empty array for undefined input', () => {
6	    expect(flattenRefinementValues(undefined)).toEqual([]);
7	  });
8	
9	  test('returns a flat list unchanged when no value nests children', () => {
10	    const values = [
11	      { value: 'Black', label: 'Black', hitCount: 3 },
12	      { value: 'White', label: 'White', hitCount: 5 },
13	    ];
14	
15	    expect(flattenRefinementValues(values)).toEqual(values);
16	  });
17	
18	  test('includes both a nested group and its children in the flattened result', () => {
19	    const values = [
20	      {
21	        value: 'clothing',
22	        label: 'Clothing',
23	        hitCount: 10,
24	        values: [{ value: '0', label: '0', hitCount: 4 }],
25	      },
26	    ];
27	
28	    expect(flattenRefinementValues(values)).toEqual([
29	      values[0],
30	      { value: '0', label: '0', hitCount: 4 },
31	    ]);
32	  });
33	
34	  test('flattens multiple levels of nesting', () => {
35	    const values = [
36	      {
37	        value: 'a',
38	        label: 'A',
39	        hitCount: 1,
40	        values: [
41	          {
42	            value: 'b',
43	            label: 'B',
44	            hitCount: 1,
45	            values: [{ value: 'c', label: 'C', hitCount: 1 }],
46	          },
47	        ],
48	      },
49	    ];
50	
51	    expect(flattenRefinementValues(values).map((v) => v.value)).toEqual(['a', 'b', 'c']);
52	  });
53	});
