1	import React from 'react';
2	import { useIntl } from 'react-intl';
3	import { Box, Checkbox, Flex, Stack, Text } from '@chakra-ui/react';
4	import { cssColorGroups } from '@salesforce/retail-react-app/app/constants';
5	// SFCC-847 — same ARIA-label messages OOTB's own CheckboxRefinements uses, reused verbatim
6	// rather than redefining equivalent strings.
7	import {
8	  ADD_FILTER,
9	  REMOVE_FILTER,
10	} from '@salesforce/retail-react-app/app/pages/product-list/partials/refinements-utils';
11	import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
12	
13	type ZimmCheckboxRefinementsProps = {
14	  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
15	  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
16	  selectedFilters: string[];
17	  /** Renders the coarse cssColorGroups swatch dot (interim — see this component's own
18	   *  docblock) next to the label. Only meaningful for the colour attribute. */
19	  showColorSwatch?: boolean;
20	};
21	
22	/**
23	 * SFCC-847 — near-identical to OOTB's own CheckboxRefinements
24	 * (`@salesforce/retail-react-app/app/pages/product-list/partials/checkbox-refinements.jsx`)
25	 * — same `toggleFilter` contract, same "hide a value that would return zero results unless
26	 * it's already selected" rule (PLP PRD §5.2 / SPR-20), same plain ADD_FILTER/REMOVE_FILTER
27	 * aria-label (no hit count — the drawer's design (Figma reference 2026-09-14) shows no
28	 * visible count next to any value, matching OOTB's own convention of only using the
29	 * HIT_COUNT message variants where the count is actually rendered).
30	 *
31	 * Adds an optional colour-family swatch dot (`showColorSwatch`), using OOTB's own coarse
32	 * `cssColorGroups` bucket-colour fallback — interim only: PLP PRD §5.4 (SPR-26)'s real
33	 * per-value swatch/pattern-image mapping in Business Manager is still Open/unconfirmed.
34	 *
35	 * @param props see ZimmCheckboxRefinementsProps
36	 */
37	export const ZimmCheckboxRefinements = ({
38	  filter,
39	  toggleFilter,
40	  selectedFilters,
41	  showColorSwatch = false,
42	}: ZimmCheckboxRefinementsProps) => {
43	  const intl = useIntl();
44	  return (
45	    <Stack spacing={1}>
46	      {filter.values?.map((value) => {
47	        const isChecked = selectedFilters.includes(String(value.value));
48	        // PLP PRD §5.2 (SPR-20): hide a value that would return zero results, unless it's
49	        // already selected (an actively-applied filter must stay visible/removable).
50	        if (value.hitCount === 0 && !isChecked) return null;
51	        const swatchColor = value.presentationId ? cssColorGroups[value.presentationId.toLowerCase()] : undefined;
52	        return (
53	          <Box key={String(value.value)}>
54	            <Checkbox
55	              isChecked={isChecked}
56	              onChange={() => toggleFilter(value, filter.attributeId, isChecked)}
57	              aria-label={intl.formatMessage(isChecked ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
58	              sx={{
59	                paddingLeft: 'var(--zimm-scale-3xs)',
60	                // Chakra paints the box on the `__control` part, so every visual override has
61	                // to target it. The same rules on the Checkbox root silently do nothing — the
62	                // label has no visible border, which is why the previous root-level
63	                // `_checked.borderColor` left the box rendering Chakra's default blue.
64	                '.chakra-checkbox__control': {
65	                  borderColor: 'var(--zimm-color-border-default)',
66	                  // Selected reads as a primary action, matching ZimmButton/ZimmSelectedChip.
67	                  _checked: {
68	                    background: 'var(--zimm-color-action-primary-bg-default)',
69	                    borderColor: 'var(--zimm-color-action-primary-bg-default)',
70	                    color: 'var(--zimm-color-action-primary-text)',
71	                  },
72	                  // Brand focus ring rather than `outline: none` — dropping the indicator
73	                  // entirely would fail WCAG 2.2 AA SC 2.4.7. Chakra's `_focusVisible` expands
74	                  // to `:focus-visible, [data-focus-visible]`, and it sets the latter on the
75	                  // control during keyboard focus, so this is the part that actually matches.
76	                  // No outline-offset here (unlike zimmLink/zimmButton): at this control's
77	                  // 16px size a detached ring reads far heavier than it does on a text link,
78	                  // so it sits flush to the box edge instead.
79	                  _focusVisible: {
80	                    outline: 'var(--zimm-focus-ring)',
81	                    outlineOffset: 0,
82	                    boxShadow: 'none',
83	                  },
84	                },
85	              }}
86	            >
87	              <Flex align="center" gap="var(--zimm-scale-2xs)">
88	                {showColorSwatch && (
89	                  <Box
90	                    boxSize="var(--zimm-icon-size-sm)"
91	                    borderRadius="full"
92	                    border="var(--zimm-border-width-default) solid var(--zimm-color-border-default)"
93	                    flexShrink={0}
94	                    background={swatchColor ?? 'transparent'}
95	                  />
96	                )}
97	                <Text as="span" textStyle="navigation">
98	                  {value.label}
99	                </Text>
100	              </Flex>
101	            </Checkbox>
102	          </Box>
103	        );
104	      })}
105	    </Stack>
106	  );
107	};
