1	import React from 'react';
2	import { Box, Flex, Stack, Text } from '@chakra-ui/react';
3	import { useIntl } from 'react-intl';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	import {
6	  ADD_FILTER,
7	  REMOVE_FILTER,
8	} from '@salesforce/retail-react-app/app/pages/product-list/partials/refinements-utils';
9	import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
10	
11	type ZimmSizeRefinementsProps = {
12	  filter: { attributeId: string; values?: ShopperSearchTypes.ProductSearchRefinementValue[] };
13	  toggleFilter: (value: { value: string | number }, attributeId: string, selected: boolean) => void;
14	  selectedFilters: string[];
15	};
16	
17	// Figma-exact chip width (node 40003890:151757) — the OOTB grid used a fixed 44px column.
18	// Treated as a MINIMUM, not a fixed size: see the layout note on SizeChipRow below.
19	// The 40px height is not here: it comes from ZimmButton's `size="medium"` recipe entry
20	// (--zimm-size-action-height-md), which matches the same Figma spec.
21	// audit-allow: Figma-sourced chip width with no equivalent --zimm-* token.
22	const CHIP_MIN_WIDTH = '89.3px';
23	
24	/**
25	 * One flat row of size chips, styled to the Figma chip spec (node 40003890:151757) via
26	 * ZimmButton's primary/secondary variants.
27	 *
28	 * Flex-wrap rather than a grid, deliberately. Figma assumes short labels (0P, 1, S, 36), and a
29	 * fixed 89.3px track fits those exactly — but SFCC returns labels the spec never accounted for,
30	 * e.g. "One Size Fits All" (needs 92.1px of text against a 49.3px content box, so it spilled
31	 * straight out of the chip) and "0P (US 2P)". A grid can't solve this: its columns are uniform,
32	 * so widening the track to fit the longest label would inflate every chip. Flex sizes each chip
33	 * independently — CHIP_MIN_WIDTH holds the design for the common case while a long label grows
34	 * only its own chip.
35	 *
36	 * The real fix is upstream: these labels should be short (the design shows "ONE SIZE"), which is
37	 * BM/AP21 configuration, not front-end. This keeps the UI intact until that lands.
38	 */
39	const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeRefinementsProps) => {
40	  const intl = useIntl();
41	
42	  return (
43	    <Flex wrap="wrap" gap="var(--zimm-scale-m)" marginTop="var(--zimm-scale-2xs)">
44	      {filter.values?.map((value) => {
45	        // Note the loose comparison, for "string == number" checks.
46	        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
47	        // Don't display refinements with no results, unless we got there by selecting too
48	        // many refinements
49	        if (value.hitCount === 0 && !isSelected) return null;
50	
51	        return (
52	          <ZimmButton
53	            key={String(value.value)}
54	            // Selected reads as a primary action (dark fill, inverse label), unselected as an
55	            // outlined chip. `size="medium"` already supplies the Figma chip metrics from
56	            // tokens — 40px height, 20px inline padding, 12px/500 uppercase type — so only
57	            // the chip width and the lighter border need stating here.
58	            variant={isSelected ? 'primary' : 'secondary'}
59	            size="medium"
60	            label={value.label}
61	            // Visible text is just the size ("0"); the announced name needs the action.
62	            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
63	            role="checkbox"
64	            ariaChecked={isSelected}
65	            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
66	            sx={{
67	              // Floor, not a fixed width — a longer label than Figma anticipated grows its
68	              // own chip rather than being clipped. flexShrink 0 stops a crowded row from
69	              // squeezing chips below the spec width.
70	              minWidth: CHIP_MIN_WIDTH,
71	              flexShrink: 0,
72	              // ZimmButton's `secondary` uses a black border; the filter chip keeps the
73	              // lighter border/secondary grey from the Figma spec instead.
74	              ...(isSelected
75	                ? {}
76	                : {
77	                    borderColor: 'var(--zimm-color-border-secondary)',
78	                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
79	                  }),
80	            }}
81	          />
82	        );
83	      })}
84	    </Flex>
85	  );
86	};
87	
88	/**
89	 * SFCC-847 — the Size facet's chip row, plus sub-group headings (e.g. Clothing/Accessories/
90	 * Shoes) when SFCC returns c_size as nested groups — the same nesting
91	 * `flattenRefinementValues` (overrides/app/utils/refinementValues.ts) already anticipates. A
92	 * flat (ungrouped) c_size refinement renders as a single ungrouped row.
93	 *
94	 * Grouping depends entirely on the shape SFCC sends: the API currently returns c_size flat, so
95	 * the ungrouped branch is what renders today. Producing the grouped design is BM configuration
96	 * (nested parent values), not a front-end change.
97	 *
98	 * @param props see ZimmSizeRefinementsProps
99	 */
100	export const ZimmSizeRefinements = ({ filter, toggleFilter, selectedFilters }: ZimmSizeRefinementsProps) => {
101	  const groups = filter.values ?? [];
102	  const isNested = groups.some((group) => group.values && group.values.length > 0);
103	
104	  if (!isNested) {
105	    return <SizeChipRow filter={filter} toggleFilter={toggleFilter} selectedFilters={selectedFilters} />;
106	  }
107	
108	  return (
109	    <Stack sx={{ gap: 'var(--zimm-scale-m)' }}>
110	      {groups.map((group) => (
111	        <Box key={String(group.value)}>
112	          {/* Sub-group heading (Clothing / Accessories / Shoes). `textStyle="body2Strong"`
113	              matches the design system's 14/18 medium letterSpacing entry; the earlier
114	              `fontStyle="italic"` was speculative and had no Figma reference (audited
115	              2026-09-16). */}
116	          <Text textStyle="body2Strong" marginBottom="var(--zimm-scale-xs)">
117	            {group.label}
118	          </Text>
119	          <SizeChipRow
120	            filter={{ attributeId: filter.attributeId, values: group.values }}
121	            toggleFilter={toggleFilter}
122	            selectedFilters={selectedFilters}
123	          />
124	        </Box>
125	      ))}
126	    </Stack>
127	  );
128	};
