const SizeChipRow = ({ filter, toggleFilter, selectedFilters }: ZimmSizeRefinementsProps) => {
  const intl = useIntl();

  return (
    <Flex wrap="wrap" gap="var(--zimm-scale-m)" marginTop="var(--zimm-scale-2xs)">
      {filter.values?.map((value) => {
        // Note the loose comparison, for "string == number" checks.
        const isSelected = selectedFilters.some((filterValue) => filterValue == value.value);
        // Don't display refinements with no results, unless we got there by selecting too
        // many refinements
        if (value.hitCount === 0 && !isSelected) return null;

        return (
          <ZimmButton
            key={String(value.value)}
            // Selected reads as a primary action (dark fill, inverse label), unselected as an
            // outlined chip. `size="medium"` already supplies the Figma chip metrics from
            // tokens — 40px height, 20px inline padding, 12px/500 uppercase type — so only
            // the chip width and the lighter border need stating here.
            variant={isSelected ? 'primary' : 'secondary'}
            size="medium"
            label={value.label}
            // Visible text is just the size ("0"); the announced name needs the action.
            ariaLabel={intl.formatMessage(isSelected ? REMOVE_FILTER : ADD_FILTER, { label: value.label })}
            role="checkbox"
            ariaChecked={isSelected}
            onClick={() => toggleFilter(value, filter.attributeId, isSelected)}
            sx={{
              // Floor, not a fixed width — a longer label than Figma anticipated grows its
              // own chip rather than being clipped. flexShrink 0 stops a crowded row from
              // squeezing chips below the spec width.
              minWidth: CHIP_MIN_WIDTH,
              flexShrink: 0,
              // ZimmButton's `secondary` uses a black border; the filter chip keeps the
              // lighter border/secondary grey from the Figma spec instead.
              ...(isSelected
                ? {}
                : {
                    borderColor: 'var(--zimm-color-border-secondary)',
                    _hover: { borderColor: 'var(--zimm-color-border-secondary)' },
                  }),
            }}
          />
        );
      })}
    </Flex>
  );
};
