108	  // inverse has no effect on the social variant (no socialInverse exists in the theme).
109	  const chakraVariant = variant === 'social' ? 'social' : `${variant}${inverse ? 'Inverse' : ''}`;
110	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
